package main

import (
	"fmt"
	"time"
)

func main() {
	ticker := time.NewTicker(20 * time.Millisecond)
	defer ticker.Stop() // avoid leaking the ticker
	for i := 0; i < 3; i++ {
		<-ticker.C
		fmt.Println("tick", i)
	}
}

