package solution

import (
	"fmt"
	"time"
)

func FormatDuration(d time.Duration) string {
	h := int(d / time.Hour)          // whole hours
	m := int((d % time.Hour) / time.Minute) // leftover whole minutes
	switch {
	case h > 0 && m > 0:
		return fmt.Sprintf("%dh%dm", h, m)
	case h > 0:
		return fmt.Sprintf("%dh", h)
	default:
		return fmt.Sprintf("%dm", m)
	}
}

codeLab.testHarness:
package solution

import (
	"testing"
	"time"
)

func TestFormatDuration(t *testing.T) {
	cases := []struct {
		d    time.Duration
		want string
	}{
		{2*time.Hour + 5*time.Minute, "2h5m"},
		{5 * time.Minute, "5m"},
		{3 * time.Hour, "3h"},
	}
	for _, c := range cases {
		if got := FormatDuration(c.d); got != c.want {
			t.Errorf("FormatDuration(%v)=%q want %q", c.d, got, c.want)
		}
	}
}

