func BusinessDaysBetween(a, b time.Time) int {
	count := 0
	// start the day after a; stop before b (both exclusive)
	for d := a.AddDate(0, 0, 1); d.Before(b); d = d.AddDate(0, 0, 1) {
		switch d.Weekday() {
		case time.Saturday, time.Sunday:
			// weekend: skip
		default:
			count++
		}
	}
	return count
}
